<script setup>
import { computed, ref } from 'vue';
import { Dialog, DialogPanel, DialogTitle } from '@headlessui/vue';
import { X, Monitor, Smartphone, Clock3, FileText, ExternalLink } from 'lucide-vue-next';
import DocumentReader from '@/Components/Lesson/DocumentReader.vue';
import HostedVideo from '@/Components/Lesson/HostedVideo.vue';
import { hostedVideo } from '@/lib/hostedVideo';
import SafeHtml from '@/Components/SafeHtml.vue';
const props = defineProps({ open: Boolean, lesson: Object, module: Object });
defineEmits(['close']);
const mobile = ref(false);
const media = computed(() => ['video', 'audio', 'pdf', 'slides'].filter(type => (props.lesson.content_type === type || props.lesson.content_type === 'mixed' || (type === 'pdf' && ['assignment', 'case_study'].includes(props.lesson.content_type))) && props.lesson[`${type}_url`]));
const activityKind = computed(() => ['quiz', 'assignment', 'case_study'].includes(props.lesson.content_type) ? props.lesson.content_type : null);
const documentManifest = url => { try { const match = new URL(url, window.location.origin).pathname.match(/^\/media\/([a-f0-9-]{36})$/i); return match ? `/authoring/documents/${match[1]}` : null; } catch { return null; } };
const directVideo = url => url.includes('/media/') || /\.(mp4|webm|mov)(\?|$)/i.test(url);
const safeUrl = url => { try { return ['https:', 'http:'].includes(new URL(url, window.location.origin).protocol) ? url : ''; } catch { return ''; } };
</script>
<template>
    <Dialog :open="open" @close="$emit('close')" class="relative z-50"><div class="fixed inset-0 bg-surface-950/70 backdrop-blur-sm" aria-hidden="true" /><div class="fixed inset-0 overflow-y-auto p-3 sm:p-8"><DialogPanel class="mx-auto max-w-5xl overflow-hidden rounded-2xl bg-surface-100 shadow-2xl"><div class="sticky top-0 z-10 flex items-center justify-between gap-3 border-b border-surface-200 bg-white px-5 py-4"><div><DialogTitle class="text-sm font-semibold">Learner preview</DialogTitle><p class="mt-1 text-[11px] text-surface-500">Current edits · no progress is recorded</p></div><div class="flex items-center gap-2"><button type="button" @click="mobile = false" :aria-pressed="!mobile" aria-label="Desktop preview" :class="['rounded-lg p-2', !mobile ? 'bg-surface-900 text-white' : 'text-surface-500']"><Monitor class="h-4 w-4" /></button><button type="button" @click="mobile = true" :aria-pressed="mobile" aria-label="Mobile preview" :class="['rounded-lg p-2', mobile ? 'bg-surface-900 text-white' : 'text-surface-500']"><Smartphone class="h-4 w-4" /></button><button type="button" @click="$emit('close')" aria-label="Close preview" class="ml-2 rounded-lg p-2 text-surface-500 hover:bg-surface-100"><X class="h-5 w-5" /></button></div></div><div class="p-4 sm:p-7"><article :class="['mx-auto rounded-2xl border border-surface-200 bg-white shadow-sm transition-all', mobile ? 'max-w-[390px] p-5' : 'max-w-3xl p-6 sm:p-10']"><p class="text-xs font-semibold uppercase tracking-wider text-primary-700">{{ module.title }}</p><h1 class="mt-3 text-3xl font-bold leading-tight">{{ lesson.title || 'Your lesson title' }}</h1><p class="mt-4 text-sm leading-6 text-surface-500">{{ lesson.summary }}</p><div class="my-6 flex items-center gap-2 border-y border-surface-100 py-3 text-xs text-surface-500"><Clock3 class="h-4 w-4" />{{ lesson.duration_minutes || '—' }} minutes</div><div class="space-y-6"><div v-if="lesson.scorm_path" class="rounded-xl border border-surface-200 bg-surface-50 p-5 text-sm leading-6 text-surface-600">SCORM {{ lesson.scorm_version }} package attached. Interactive playback is available from the saved learner lesson.</div><template v-else v-for="type in media" :key="type"><HostedVideo v-if="type === 'video' && hostedVideo(lesson.video_url)" :key="lesson.video_url" :url="lesson.video_url" /><video v-else-if="type === 'video' && directVideo(lesson.video_url)" :src="safeUrl(lesson.video_url)" controls preload="metadata" class="w-full rounded-xl bg-black" /><audio v-else-if="type === 'audio'" :src="safeUrl(lesson.audio_url)" controls preload="metadata" class="w-full" /><DocumentReader v-else-if="['pdf', 'slides'].includes(type)" :manifest-url="documentManifest(lesson[`${type}_url`])" :title="type === 'pdf' ? 'Lesson PDF' : 'Lesson presentation'" /><a v-else :href="safeUrl(lesson[`${type}_url`])" target="_blank" rel="noopener noreferrer" class="flex items-center gap-3 rounded-xl border border-surface-200 bg-surface-50 p-4 text-sm font-medium text-primary-700"><FileText class="h-5 w-5" />Open {{ type === 'slides' ? 'presentation' : 'video' }}<ExternalLink class="ml-auto h-4 w-4" /></a></template><SafeHtml v-if="['text', 'mixed', 'assignment', 'case_study'].includes(lesson.content_type) && lesson.text_content && !lesson.scorm_path" :content="lesson.text_content" /><div v-if="activityKind" class="rounded-xl border border-primary-100 bg-primary-50 p-5 text-sm text-primary-900"><p class="font-semibold">{{ activityKind === 'quiz' ? 'Quiz' : activityKind === 'assignment' ? 'Assignment submission' : 'Case study response' }}</p><p v-if="activityKind === 'quiz'" class="mt-1 text-primary-800">{{ lesson.activity?.questions?.length || 0 }} questions · pass mark {{ lesson.activity?.passing_score_pct || 70 }}%{{ lesson.activity?.time_limit_minutes ? ` · ${lesson.activity.time_limit_minutes} min` : '' }}. Learners start the quiz from this lesson.</p><ol v-else-if="activityKind === 'case_study'" class="mt-2 list-decimal space-y-1 pl-5 text-primary-800"><li v-for="(prompt, index) in (lesson.activity?.prompts || []).filter(item => item.trim())" :key="index">{{ prompt }}</li></ol><p v-else class="mt-1 text-primary-800">Learners write a response{{ lesson.activity?.allow_file_upload ? ' and can attach files' : '' }}. Scored out of {{ lesson.activity?.max_score || 100 }}.</p></div><details v-if="lesson.video_transcript" class="rounded-xl bg-surface-50 p-4"><summary class="cursor-pointer text-sm font-semibold">Transcript</summary><p class="mt-3 whitespace-pre-wrap text-sm leading-7 text-surface-600">{{ lesson.video_transcript }}</p></details><section v-if="lesson.key_terms?.some(term => term.term)" class="rounded-xl bg-surface-50 p-5"><h2 class="text-sm font-semibold">Key terms</h2><dl class="mt-4 space-y-3"><div v-for="term in lesson.key_terms.filter(term => term.term)" :key="term.term"><dt class="text-sm font-semibold">{{ term.term }}</dt><dd class="mt-1 text-sm leading-6 text-surface-600">{{ term.definition }}</dd></div></dl></section></div></article></div></DialogPanel></div></Dialog>
</template>
